package com.biocircular.auditoria; import jakarta.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@Entity @Table(name="evento_auditoria") class Evento{@Id @GeneratedValue UUID id; UUID usuarioExternoId; String correoUsuario,accion,modulo,recursoTipo; UUID recursoExternoId; OffsetDateTime fechaHora=OffsetDateTime.now(); String resultado="EXITOSO",descripcion; public UUID getId(){return id;}}
interface Eventos extends JpaRepository<Evento,UUID>{Page<Evento> findByUsuarioExternoId(UUID id,Pageable p);Page<Evento> findByModuloIgnoreCase(String n,Pageable p);}
record EventoRequest(UUID usuarioExternoId,String correoUsuario,@NotBlank String accion,@NotBlank String modulo,@NotBlank String recursoTipo,UUID recursoExternoId,@NotBlank String descripcion,String resultado){}
@RestController @RequestMapping("/api/auditoria") public class AuditoriaController{final Eventos r;AuditoriaController(Eventos x){r=x;}@GetMapping Page<Evento> all(Pageable p){return r.findAll(p);}@GetMapping("/{id}")Evento one(@PathVariable UUID id){return r.findById(id).orElseThrow();}@GetMapping("/usuario/{id}")Page<Evento> user(@PathVariable UUID id,Pageable p){return r.findByUsuarioExternoId(id,p);}@GetMapping("/modulo/{n}")Page<Evento> mod(@PathVariable String n,Pageable p){return r.findByModuloIgnoreCase(n,p);}@GetMapping("/fecha")Page<Evento> fecha(Pageable p){return r.findAll(p);}@PostMapping({"","/eventos"})ResponseEntity<Evento> post(@Valid @RequestBody EventoRequest q){Evento e=new Evento();e.usuarioExternoId=q.usuarioExternoId();e.correoUsuario=q.correoUsuario();e.accion=q.accion();e.modulo=q.modulo();e.recursoTipo=q.recursoTipo();e.recursoExternoId=q.recursoExternoId();e.descripcion=q.descripcion();if(q.resultado()!=null)e.resultado=q.resultado();return ResponseEntity.status(201).body(r.save(e));}}
